@IsTest
private class TestAccountDeletion {
    @IsTest
    static void TestDeleteAccountWithOneOpportunity() {
        Account acct = new Account(Name = 'Test Account');
        insert as user acct;
        insert as user new Opportunity(Name = acct.Name + ' Opp', StageName = 'Prospecting',
            CloseDate = System.today().addMonths(1), AccountId = acct.Id);

        Test.startTest();
        Database.DeleteResult result = Database.delete(acct, false, AccessLevel.USER_MODE);
        Test.stopTest();

        Assert.isFalse(result.isSuccess());
        Assert.isTrue(result.getErrors().size() > 0);
        Assert.areEqual('Cannot delete account with related opportunities.',
                        result.getErrors()[0].getMessage());
    }
}

@IsTest
public class TestDataFactory {
    public static List<Account> createAccountsWithOpps(Integer numAccts, Integer numOppsPerAcct) {
        List<Account> accts = new List<Account>();
        for (Integer i = 0; i < numAccts; i++) {
            accts.add(new Account(Name = 'TestAccount' + i));
        }
        insert accts;
        List<Opportunity> opps = new List<Opportunity>();
        for (Account a : accts) {
            for (Integer k = 0; k < numOppsPerAcct; k++) {
                opps.add(new Opportunity(Name = a.Name + ' Opp ' + k, StageName = 'Prospecting',
                    CloseDate = System.today().addMonths(1), AccountId = a.Id));
            }
        }
        insert opps;          // 반복문 밖에서 한 번에 DML
        return accts;
    }
}

@TestSetup
static void makeData() {
    TestDataFactory.createAccountsWithOpps(200, 1);
}
@IsTest
static void bulkDelete() {
    List<Account> accts = [SELECT Id FROM Account];
    Test.startTest();
    Database.DeleteResult[] results = Database.delete(accts, false);
    Test.stopTest();
    for (Database.DeleteResult dr : results) Assert.isFalse(dr.isSuccess());
}
